def preserve_existing_plans(apps, schema_editor):
    from zoneinfo import ZoneInfo
    Plan = apps.get_model("training", "TrainingPlan")
    Slot = apps.get_model("training", "TrainingScheduleSlot")
    zone = ZoneInfo("Asia/Shanghai")
    for plan in Plan.objects.using(schema_editor.connection.alias).iterator():
        values = {}
        if plan.schedule_published_at or plan.status in {"published", "completed", "archived"}:
            # 旧状态没有独立的计划发布时间；优先沿用已有排班时间，其他沿用最后保存时间作为兼容标记。
            values["published_at"] = plan.schedule_published_at or plan.updated_at
        for period in ("early", "morning", "afternoon", "evening"):
            slots = list(Slot.objects.using(schema_editor.connection.alias).filter(day__training_plan=plan, period=period).values_list("starts_at", "ends_at"))
            if not slots or any(start is None or end is None for start, end in slots):
                continue
            pairs = {(start.astimezone(zone).time(), end.astimezone(zone).time()) for start, end in slots}
            if len(pairs) == 1:
                start, end = pairs.pop()
                if start < end:
                    values[f"{period}_start"], values[f"{period}_end"] = start, end
        Plan.objects.using(schema_editor.connection.alias).filter(pk=plan.pk).update(**values) if values else None
    # 旧待审申请缺少教练确认链，保留原申请并终止，要求按新规则重新提交。
    Change = apps.get_model("training", "TrainingScheduleChange")
    from django.utils import timezone
    Change.objects.using(schema_editor.connection.alias).filter(status="pending").update(status="rejected", review_note="审批流程升级，原安排未变；请按新规则重新提交申请。", reviewed_at=timezone.now(), updated_at=timezone.now())


